def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pts=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,9)]
    if not pts: return g
    r0=min(r for r,c,v in pts); r1=max(r for r,c,v in pts)
    c0=min(c for r,c,v in pts); c1=max(c for r,c,v in pts)
    shape=[(r-r0,c-c0,v) for r,c,v in pts]
    out=[row[:] for row in g]
    # Reproduce the colored object's occupied-cell mask wherever all those
    # locations are empty/background zeros; leave all nonzero cells intact.
    for r in range(h-(r1-r0+1)+1):
      for c in range(w-(c1-c0+1)+1):
        if all(g[r+dr][c+dc]==0 for dr,dc,v in shape):
          for dr,dc,v in shape: out[r+dr][c+dc]=v
    return out

